INSERT INTO `careerjet` (`id`, `title`, `url`, `location`, `posted`, `scraped`, `company`, `description`, `type`) VALUES
(212512, 'Πωλητές - Πωλήτριες Αχαρνές 2', 'https://www.careerjet.gr/jobad/gr83edbf77826124f17979a55e449b97c7', 'Αχαρνές, Αττικής', 'Πριν 3 ώρες', '2026-03-26 11:00:49', 'Pet City Group AEBE', 'Έχεις πάθος για τις πωλήσεις? Θέλεις να εργαστείς και να εξελίξεις την καριέρα σου σε ένα δυναμικό και συνεχώς αναπτυσσόμενο περιβάλλον? Αγαπάς τα κατοικίδια όσο εμείς?Μην περιμένεις άλλο! Κάνε τώρα την αίτησή σου και γίνε μέλος της πιο Pawsome ομάδας🐾Ποιοι είμαστε;Ο Όμιλος Pet City είναι η μεγαλύτερη αλυσίδα καταστημάτων τροφών και αξεσουάρ κατοικίδιων ζώων στην Ελλάδα, με παρουσία άνω των 35 χρόνων στο χώρο του λιανικού εμπορίου. Η ομάδα μας αποτελείται από ένα δίκτυο 100+ καταστημάτων και 800 ανθρώπων που αγαπούν τα ζώα, τους αρέσει η εξέλιξη και η γνώση και δίνουμε καθημερινά τον καλύτερό μας εαυτό στην Pet εξυπηρέτηση.Στα πλαίσια της ανάπτυξης μας αναζητούμε ενθουσιώδεις υποψηφίους με πάθος για τις πωλήσεις και προσανατολισμένους στην καλύτερη δυνατή εξυπηρέτηση των πελατών μας για μερική ή πλήρη απασχόληση για τη θέση Πωλητής/τρια στο κατάστημά μας στις Αχαρνές 2.Τι κάνει ένα Sales Associate να ξεχωρίζει;Ως Sales Associate είσαι η καρδιά των καταστημάτων μας. Με το χαμόγελο και την ευχάριστη διάθεση σου συμβουλεύεις και καθοδηγείς κάθε Pet Parent, ώστε να μας εμπιστεύονται καθημερινά τόσο για τις αγορές τους, όσο και για την φροντίδα των αγαπημένων τους pets. Κάποια από τα χαρακτηριστικά που θα πρέπει ένας πετυχημένος Sales Associate να έχει, είναι ο προσανατολισμός στον πελάτη, ευχέρεια στην επικοινωνία, ευγένεια, αξιοπιστία, να είναι στοργικός, φιλόζωος, συνεπής και προσαρμοστικός και πάνω από όλα να θέλει να μάθει και να εξελιχθεί εντός του Ομίλου μας!Οι αρμοδιότητες σας:Υποδοχή, ενημέρωση και καθοδήγηση πελατών για την καλύτερη επιλογή αγοράςΠωλήσεις και εξυπηρέτηση μετά την πώληση εξασφαλίζοντας ένα θετικό customer experienceΈλεγχος stock καταστήματος και αναπλήρωση όταν είναι απαραίτητο για την καλύτερη δυνατή εξυπηρέτηση των αναγκώνΔιεκπεραίωση των παραγγελιών, παραλαβή και οργάνωση αποθήκης και του κεντρικού χώρου του καταστήματοςΠαραλαβή και έλεγχος παραγγελίαςΧρήση ταμειακής μηχανήςΑπαραίτητα προσόντα:Διάθεση για εκπαίδευση και εξέλιξηΠροσανατολισμός στην εξυπηρέτηση του πελάτηΒασική γνώση αγγλικών και Η/ΥΕυχέρεια στην επικοινωνία και ευχάριστη προσωπικότηταΥπευθυνότητα και συνέπειαΟμαδικό πνεύμα συνεργασίαςΟι παροχές μας:💶 Σταθερό πακέτο αποδοχών🏆 Πρόγραμμα επιβράβευσης για την επίτευξη των εταιρικών στόχων🎓 Συνεχής εκπαίδευση και ανάπτυξη💼 Ευκαιρίες επαγγελματικής εξέλιξης σε Supervisor --> Store Supervisor --> Store Manager μέσα σε ένα δυναμικό και συνεχώς αναπτυσσόμενο περιβάλλον💊 Προνομιακές τιμές και εκπτώσεις σε δίκτυο συνεργαζόμενων εταιρειών για παροχές υγείας, ευ ζην και ασφάλισης🏷️ Εκπτώσεις για το προσωπικό στα προϊόντα και της υπηρεσίες μας. Pet City Group AEBE', 'n/a'),
(212513, 'Πωλητές - Πωλήτριες Κορυδαλλός (6ωρη μερική απασχόληση)', 'https://www.careerjet.gr/jobad/gr8d66959ba3d4da0dbb0ec27d26e62c3a', 'Κορυδαλλός, Αττικής', 'Πριν 6 ώρες', '2026-03-26 11:00:59', 'Pet City Group AEBE', 'Έχεις πάθος για τις πωλήσεις? Θέλεις να εργαστείς και να εξελίξεις την καριέρα σου σε ένα δυναμικό και συνεχώς αναπτυσσόμενο περιβάλλον? Αγαπάς τα κατοικίδια όσο εμείς?Μην περιμένεις άλλο! Κάνε τώρα την αίτησή σου και γίνε μέλος της πιο Pawsome ομάδας🐾Ποιοι είμαστε;Ο Όμιλος Pet City είναι η μεγαλύτερη αλυσίδα καταστημάτων τροφών και αξεσουάρ κατοικίδιων ζώων στην Ελλάδα, με παρουσία άνω των 35 χρόνων στο χώρο του λιανικού εμπορίου. Η ομάδα μας αποτελείται από ένα δίκτυο 100+ καταστημάτων και 800 ανθρώπων που αγαπούν τα ζώα, τους αρέσει η εξέλιξη και η γνώση και δίνουμε καθημερινά τον καλύτερό μας εαυτό στην Pet εξυπηρέτηση.Στα πλαίσια της ανάπτυξης μας αναζητούμε ενθουσιώδεις υποψηφίους με πάθος για τις πωλήσεις και προσανατολισμένους στην καλύτερη δυνατή εξυπηρέτηση των πελατών μας για 6ωρη μερική απασχόληση για τη θέση Πωλητής/τρια στο κατάστημά μας στον Κορυδαλλό.Τι κάνει ένα Sales Associate να ξεχωρίζει;Ως Sales Associate είσαι η καρδιά των καταστημάτων μας. Με το χαμόγελο και την ευχάριστη διάθεση σου συμβουλεύεις και καθοδηγείς κάθε Pet Parent, ώστε να μας εμπιστεύονται καθημερινά τόσο για τις αγορές τους, όσο και για την φροντίδα των αγαπημένων τους pets. Κάποια από τα χαρακτηριστικά που θα πρέπει ένας πετυχημένος Sales Associate να έχει, είναι ο προσανατολισμός στον πελάτη, ευχέρεια στην επικοινωνία, ευγένεια, αξιοπιστία, να είναι στοργικός, φιλόζωος, συνεπής και προσαρμοστικός και πάνω από όλα να θέλει να μάθει και να εξελιχθεί εντός του Ομίλου μας!Οι αρμοδιότητες σας:Υποδοχή, ενημέρωση και καθοδήγηση πελατών για την καλύτερη επιλογή αγοράςΠωλήσεις και εξυπηρέτηση μετά την πώληση εξασφαλίζοντας ένα θετικό customer experienceΈλεγχος stock καταστήματος και αναπλήρωση όταν είναι απαραίτητο για την καλύτερη δυνατή εξυπηρέτηση των αναγκώνΔιεκπεραίωση των παραγγελιών, παραλαβή και οργάνωση αποθήκης και του κεντρικού χώρου του καταστήματοςΠαραλαβή και έλεγχος παραγγελίαςΧρήση ταμειακής μηχανήςΑπαραίτητα προσόντα:Διάθεση για εκπαίδευση και εξέλιξηΠροσανατολισμός στην εξυπηρέτηση του πελάτηΒασική γνώση αγγλικών και Η/ΥΕυχέρεια στην επικοινωνία και ευχάριστη προσωπικότηταΥπευθυνότητα και συνέπειαΟμαδικό πνεύμα συνεργασίαςΟι παροχές μας:💶 Σταθερό πακέτο αποδοχών🏆 Πρόγραμμα επιβράβευσης για την επίτευξη των εταιρικών στόχων🎓 Συνεχής εκπαίδευση και ανάπτυξη💼 Ευκαιρίες επαγγελματικής εξέλιξης σε Supervisor --> Store Supervisor --> Store Manager μέσα σε ένα δυναμικό και συνεχώς αναπτυσσόμενο περιβάλλον💊 Προνομιακές τιμές και εκπτώσεις σε δίκτυο συνεργαζόμενων εταιρειών για παροχές υγείας, ευ ζην και ασφάλισης🏷️ Εκπτώσεις για το προσωπικό στα προϊόντα και της υπηρεσίες μας. Pet City Group AEBE', 'n/a'),
(212514, 'Σύμβουλος Ανάπτυξης Συστημάτων Διαχείρισης ISO', 'https://www.careerjet.gr/jobad/gr61a83d90daa4244ad1e87bc256140984', 'Θεσσαλονίκη', 'Πριν 11 ώρες', '2026-03-26 11:01:08', 'SAMARAS & ASSOCIATES LTD', 'Η ΣΑΜΑΡΑΣ & ΣΥΝΕΡΓΑΤΕΣ Ε.Π.Ε. (www.exyppsamaras.gr), κορυφαία εταιρεία στον χώρο της παροχής συμβουλευτικών υπηρεσιών ως ΕΞΥΠΠ, δραστηριοποιείται δυναμικά στους τομείς Υγείας, Ασφάλειας, Ποιότητας & Περιβάλλοντος, συμμετέχοντας στα μεγαλύτερα κατασκευαστικά έργα της χώρας.Στο πλαίσιο ανάπτυξης των δραστηριοτήτων της, η εταιρεία αναζητά Σύμβουλο Ανάπτυξης Συστημάτων Διαχείρισης ISO με εξειδίκευση σε συστήματα Ποιότητας, Περιβάλλοντος και Υγείας και Ασφάλειας της Εργασίας.Η θέσηΩς σύμβουλος Συστημάτων Διαχείρισης καλείσαι να αναπτύξεις την απαιτητή από το αντίστοιχο πρότυπο (ISO Standard) τεκμηρίωση σύμφωνα με τη δομή και λειτουργία της επιχείρησης και να συμβάλεις πέραν της πιστοποίησης της εταιρίας, στη βελτίωση του τρόπου λειτουργίας της, τον τρόπο αντιμετώπισης των διαφόρων απειλών ή/και ευκαιριών που προκύπτουν από τη σημερινή εποχή και την εξαγωγή χρήσιμων για τη διοίκηση συμπερασμάτων.Οι εταιρίες διαφέρουν ως προς το αντικείμενο δραστηριότητας, το μέγεθος, το λόγο ανάπτυξης του Συστήματος Διαχείρισης (ISO MS), αλλά αυτό αποτελεί μια διαρκή πρόκληση και εναλλαγή στην εργασία μας.Η προσέγγισή μας είναι αυτής της Ομάδας και σκοπός μας είναι η διαρκής εξέλιξη των Στελεχών μας μέσα από την εκπαίδευση, τη συνεργασία με άλλα Στελέχη και φυσικά τη δουλειά τους. Η αρχή μας είναι η απόδοση προστιθέμενης αξίας στις υπηρεσίες μας, η ικανοποίηση των πελατών μας και η εταιρική μας βελτίωση.Κύριες Αρμοδιότητες Επαφή με δυνητικούς πελάτες Κοστολόγηση έργων και σύνταξη προσφορών Σχεδιασμός υλοποίησης έργων, χρονοδιάγραμμα και παραδοτέα Συμμετοχή στην σύνταξη διαδικασιών και εντύπων Συμμετοχή στην εκπόνηση αναλύσεων διακινδύνευσης (Risk Assessment) Συμμετοχή στην διενέργεια εσωτερικών επιθεωρήσεων και ανασκοπήσεων Διοίκησης Παρακολούθηση εξέλιξης έργων και ενημέρωση Διοίκησης Συμμετοχή σε εκπαιδεύσεις Συμμετοχή σε εταιρικές δράσεις Απαραίτητα Προσόντα Δίπλωμα Μηχανικού ή Πτυχίο με κατεύθυνση ή ειδίκευση στην Πληροφορική Γνώση των προτύπων ISO 9001, ISO 14001, ISO 45001 Επικοινωνιακές δεξιότητες και ικανότητα επίλυσης προβλημάτων Αναλυτική σκέψη και οργανωτικές δεξιότητες Ομαδικό πνεύμα και διάθεση συνεργασίας με Ομάδα Έργου Ικανότητα παράλληλης υλοποίησης πολλαπλών εργασιών Καλή γνώση Αγγλικής γλώσσας (ανάγνωση, σύνταξη και επικοινωνία) Πολύ καλή γνώση MS Office Δίπλωμα Β\' κατηγορίας ΙΧ αυτοκίνητο Δυνατότητα ταξιδιών Επιθυμητά προσόντα Εργασιακή εμπειρία σε θέματα ανάπτυξης ή/και συντήρησης, εφαρμογής Συστημάτων Διαχείρισης (ISO MS). Πιστοποίηση ή επιμόρφωση επικεφαλής επιθεωρητή ή εσωτερικού επιθεωρητή. Γνώση λοιπών προτύπων (ISO 27001, ISO 39001, ISO 50001 κλπ.) Παροχές Άριστο περιβάλλον εργασίας Ελκυστικό πακέτο αποδοχών Προοπτικές εξέλιξης Διαρκής εκπαίδευση Με την υποβολή του βιογραφικού σας δηλώνετε ότι έχετε ενημερωθεί για την της «ΣΑΜΑΡΑΣ & ΣΥΝΕΡΓΑΤΕΣ Ε.Π.Ε.» και παρέχετε τη συγκατάθεσή σας για την επεξεργασία των προσωπικών σας δεδομένων αποκλειστικά για τον σκοπό της αξιολόγησης της υποψηφιότητάς σας. Τα δεδομένα διατηρούνται για τρία (3) έτη και ενδέχεται να διαβιβαστούν σε εταιρείες του Ομίλου και σε παρόχους υποστήριξης δικτύων/μηχανογράφησης. Μπορείτε να ασκήσετε τα δικαιώματά σας, συμπεριλαμβανομένης της ανάκλησης συγκατάθεσης, στο gdpr@exyppsamaras.gr. SAMARAS & ASSOCIATES LTD', 'n/a'),
(212515, 'Πωλητές/ Πωλήτριες Ρόδος', 'https://www.careerjet.gr/jobad/gr91ad05f867fd470935d774d4b3d9eaa0', 'Ρόδος, Δωδεκανήσου', 'Πριν 11 ώρες', '2026-03-26 11:01:18', 'FunkyBuddha', 'Περιγραφή εταιρείαςΗ Funky Buddha, σήμα της εταιρείας Αltex S.A., που δραστηριοποιείται στο χώρο της σύγχρονης ανδρικής και γυναικείας ένδυσης, στο πλαίσιο της δυναμικής της ανάπτυξης, ζητά πωλητές/πωλήτριες για πλήρη/μερική απασχόληση στο κατάστημα της εταιρείας στη Ρόδο.Περιγραφή θέσης εργασίας Εξυπηρέτηση πελατών Εφαρμογή πολιτικών και διαδικασιών με βάση τα standards της εταιρείας Συμβολή στην επίτευξη στόχων του καταστήματος και κατ’ επέκταση στην επίτευξη των εταιρικών στόχων Δημιουργία σχέσεων εμπιστοσύνης με τους πελάτες. Ανταπόκριση σε παράπονα πελατών Υλοποίηση λειτουργικών διαδικασιών στο χώρο πώλησης Αναπλήρωση εμπορευμάτων, συμμετοχή στις διαδικασίες απογραφής, ταμειακή διαχείριση Επαγγελματικά προσόντα Τουλάχιστον 2ετή εμπειρία στο χώρο των πωλήσεων. Εμπειρία στο χώρο της casual ένδυσης θα θεωρηθεί προσόν Πτυχίο ΑΕΙ, ΤΕΙ/ ΑΤΕΙ θα θεωρηθεί επιπρόσθετο προσόν Πολύ καλή γνώση Αγγλικής γλώσσας (προφορικά και γραπτά) Πολύ καλή γνώση Η/Υ (MS OFFICE). Η γνώση ταμείου θα συνεκτιμηθεί Ευχέρεια λόγου, ευγένεια και άνεση στην επικοινωνία Ομαδικό πνεύμα συνεργασίας με έμφαση στην εξυπηρέτηση του πελάτη Ενδιαφέρον για το χώρο της μόδας και πάθος για τις πωλήσεις Πρόσθετες πληροφορίες Διατακτικές σίτισης σε μηνιαία βάση Συμμετοχή στο retail bonus του καταστήματος, βάση μηνιαίας στοχοθέτησης Σημαντική έκπτωση στα προϊόντα της εταιρείας Ετήσιο Check up Δυνατότητες εξέλιξης λόγω συνεχούς ανάπτυξης FunkyBuddha', 'n/a'),
