INSERT INTO `careerjet` (`id`, `title`, `url`, `location`, `posted`, `scraped`, `company`, `description`, `type`) VALUES
(213338, 'Café Team Member 15-20h', 'https://www.careerjet.gr/jobad/gr4ef3ba5f816146be68164e31d2b67695', 'Ελλάδα', 'Πριν 11 ώρες', '2026-04-09 10:01:35', 'ARKET Προβολή όλων των θέσεων εργασίας', 'Περιγραφή εταιρείαςΗ ARKET προσφέρει βασικές συλλογές για γυναίκες, άνδρες, παιδιά και το σπίτι, μαζί με ένα εποχιακό χορτοφαγικό καφέ και καφετέρια. Εμπνευσμένο από την απλότητα, τη φύση και την αισθητική της αργής ζωής, οι συλλογές περιλαμβάνουν ενδύματα, αντικείμενα και τρόφιμα που κατασκευάζονται προσεκτικά και επιμελούνται καλλιτεχνικά για μια πιο όμορφη καθημερινή ζωή.Περιγραφή θέσης εργασίαςΩς πολύτιμο μέλος της ομάδας του καφέ μας, θα εργάζεστε σε ένα ζεστό και φιλόξενο περιβάλλον εμπνευσμένο από τη Nordic αισθητική, ενσωματωμένο αρμονικά στο κατάστημά μας. Η προτεραιότητά σας θα είναι πάντα η παροχή εξαιρετικής ποιότητας, άριστης εξυπηρέτησης και αξέχαστων εμπειριών για κάθε επισκέπτη. Με φυσική ικανότητα να βάζετε τον πελάτη στο επίκεντρο και να προσαρμόζεστε στις ανάγκες του, θα συμβάλλετε στη δημιουργία μιας εξατομικευμένης και εμπνευσμένης ατμόσφαιρας καφέ, βασισμένης στην τοπική κουλτούρα και φιλοξενία.Θα έχετε την ευκαιρία να προσφέρετε υψηλού επιπέδου εξυπηρέτηση σε κάθε σημείο επαφής — από το θερμό καλωσόρισμα των επισκεπτών έως την προσεκτική κάλυψη των αναγκών τους με αυθεντικό και στοχαστικό τρόπο. Θα είστε υπεύθυνοι για την προετοιμασία και την προσφορά ποιοτικών φαγητών και ροφημάτων, διατηρώντας σταθερά τα πρότυπα αριστείας μας.Σε αυτόν τον ρόλο, θα παίξετε επίσης βασικό ρόλο στην προώθηση των αξιών, της κουλτούρας και της φιλοσοφίας του καφέ, συμβάλλοντας στην ομαλή καθημερινή λειτουργία του καφέ εντός του καταστήματος.Η προηγούμενη εμπειρία στον τομέα της εστίασης ή της εξυπηρέτησης πελατών είναι πλεονέκτημα — αλλά όχι απαραίτητη. Αυτό που έχει μεγαλύτερη σημασία είναι το πάθος σας για τη φιλοξενία, η προθυμία σας να μάθετε και η δέσμευσή σας να προσφέρετε εξαιρετικές εμπειρίες στους επισκέπτες.Επαγγελματικά προσόντα Πιστοποιητικό υγείας από γιατρό Πιστοποιητικό εκπαίδευσης για την Ασφάλεια Τροφίμων – Επίπεδο 1 Εστίαση στον πελάτη: πρόθυμος/η να αλληλεπιδρά με τους πελάτες και να προσφέρει υψηλά επίπεδα εξυπηρέτησης Προσαρμοστικότητα και ευελιξία Άτομο με δράση Καλή επικοινωνία: ουσιαστικό ενδιαφέρον για τους ανθρώπους και ενεργή ακρόαση των αναγκών και των απόψεών τους Ανοιχτός/ή στη μάθηση και στην αναζήτηση ευκαιριών ανάπτυξης Γνήσιο πάθος για το φαγητό, τα ροφήματα και το brand ARKET, με έντονη επιθυμία να μοιραστείτε τον ενθουσιασμό και τις γνώσεις σας με τους πελάτες Άνεση με ευέλικτα ωράρια εργασίας Άριστη γνώση της ελληνικής γλώσσας, η γνώση της αγγλικής γλώσσας θα θεωρηθεί επιπλέον πλεονέκτημα Πρόσθετες πληροφορίεςΠρόκειται για θέση μερικής απασχόλησης (15-20 ώρες την εβδομάδα), που περιλαμβάνει εργασία τα Σαββατοκύριακα και τις νυχτερινές ώρες.Κάνε αίτηση στέλνοντας το βιογραφικό σου στα αγγλικά όσο το δυνατόν γρηγορότερα, αλλά όχι αργότερα από τις 30.04.2026. Λόγω πολιτικών δεδομένων, δεχόμαστε αιτήσεις μόνο μέσω της σελίδας καριέρας.ΠαροχέςΠαρέχουμε σε όλους τους εργαζομένους μας στον όμιλο H&M ελκυστικές παροχές με πολλές ευκαιρίες εξέλιξης παγκοσμίως. Κάθε υπάλληλός μας απολαμβάνει έκπτωση προσωπικού, η οποία ισχύει για όλα τα brands του Ομίλου H&M, είτε σε φυσικά καταστήματα είτε online. Πιο συγκεκριμένα, τα brands για τα οποία ισχύει η έκπτωση είναι τα H&M, COS, Weekday, Monki, H&M HOME, & Other Stories, ARKET, και Afound. Εκτός από την έκπτωση προσωπικού, όλοι οι εργαζόμενοί μας συμμετέχουν επίσης στο πρόγραμμα κινήτρων H&M - HIP. Περισσότερες λεπτομέρειες σχετικά με το πρόγραμμα μπορείς να βρεις .Επιπλέον, οι συνάδελφοι που είναι στην Ελλάδα παίρνουν επίσης:: Επιβράβευση πολυετούς απασχόλησης - Επέτειος 10ετίας, 15 ετίας & 20 ετίας Δωροκάρτα για τη γέννηση παιδιού Ιδιωτική ιατρο-φαρμακευτική Ασφάλιση Ιδιωτική Ασφάλιση Ζωής Επιβράβευση Συνταξιοδότησης Πρόγραμμα Σύστασης Υποψηφίων Διατακτικές Σίτισης Απεριόριστες ευκαιρίες καριέρας Επίδομα ενδυμασίας (έως 800 ευρώ ετησίως) Ένταξη και ΔιαφορετικότηταΣτον Όμιλο H&M, δεσμευόμαστε να δημιουργούμε και να εξασφαλίζουμε εργασιακούς χώρους χωρίς αποκλεισμούς, ενισχύοντας την διαφορετικότητα και την ίση μεταχείριση σε όλο τον οργανισμό μας. Οι ομάδες μας θέλουμε να αποτελούνται από ποικίλα άτομα που συνδυάζουν τις γνώσεις, την εμπειρία και τις ιδέες τους. Η ύπαρξη ενός ποικιλόμορφου εργατικού δυναμικού έχει θετικό αντίκτυπο στον τρόπο αντιμετώπισης των προκλήσεων, στην αντίληψή μας για το πόσα μπορούμε να επιτύχουμε, και στον τρόπο επικοινωνίας με συναδέλφους και πελάτες παγκοσμίως. Ως εκ τούτου, όλες οι πτυχές της διαφορετικότητας λαμβάνονται υπόψη στη διαδικασία πρόσληψής μας. ARKET', 'n/a'),
(213339, 'Σύμβουλος Πώλησης Ηλεκτρολογικού Υλικού και Τεχνολογίας _ Χαλάνδρι', 'https://www.careerjet.gr/jobad/grfbaed815d510c3b229525f5774a9306d', 'Χαλάνδρι, Αττικής', 'Πριν 3 ώρες', '2026-04-09 10:01:41', 'ΚΑΥΚΑΣ Προβολή όλων των θέσεων εργασίας', '⚡ Σε συναρπάζει ο κλάδος της ηλεκτρολογίας & νέων τεχνολογιών και σου αρέσει να βρίσκεις τις βέλτιστες λύσεις για κάθε ανάγκη;👉 Τότε…#ElectrifyYourCareer στη δυνατή μας ομάδα!Στην ΚΑΥΚΑΣ αναζητούμε team players με πάθος για συνεχή μάθηση και εξέλιξη!«Η δύναμή μας είναι οι άνθρωποί μας🤝» και το δείχνουμε έμπρακτα με: Μηνιαίο Μισθό που ξεκινά από 1000€ μικτά & επιπλέον παροχές Ετήσιο Bonus απόδοσης Επιπλέον γιορτινά επιδόματα Χριστουγέννων & Πάσχα (πέραν των νόμιμων) Σύμβαση εργασίας για 5θημερο / 8ωρο- χωρίς εργάσιμες Κυριακές! Επιπλέον ημέρες αργίας για περισσότερο χρόνο για εσένα και την οικογένειά σου Οικογενειακή στήριξη: μηνιαίο επίδομα, σχολικά είδη & γιορτινά δώρα για όλα τα KAFKASian Kids Ειδικές εκπτώσεις για όλα τα μέλη της ομάδας μας Wellbeing δράσεις & ομαδικές εμπειρίες που μας φέρνουν πιο κοντά Και φυσικά… Συνεχής εκπαίδευση & πιστοποιήσεις, προσαρμοσμένα στο ρόλο σου μέσω του Kafkas Institute of Training & Development Ασύγχρονη εκπαίδευση μέσω της πλατφόρμας KAFKAS “Blue”, για να μαθαίνεις στον δικό σου ρυθμό Δυνατότητες εξέλιξης στο Δίκτυο Καταστημάτων ή σε άλλες Διευθύνσεις Δεν είμαστε απλά πιστοποιημένοι - είμαστε βραβευμένοι! 👏👏👏🏆 Για 11 χρόνια, η ΚΑΥΚΑΣ βρίσκεται στο top 10 των Best Workplaces στην Ελλάδα: μια διάκριση που μας κάνει υπερήφανους!Αν όσα διάβασες σε εμπνέουν, στείλε σήμερα το βιογραφικό σου και γίνε κομμάτι της δυνατής μας ομάδας!#TeamKafkas #ElectrifyYourCareer #BestWorkplace #ΑpplyToday ΚΑΥΚΑΣ', 'n/a'),
